CREATE OR REPLACE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `Sales by Category` AS select `Categories`.`CategoryID` AS `CategoryID`,`Categories`.`CategoryName` AS `CategoryName`,`Products`.`ProductName` AS `ProductName`,sum(`Order Details Extended`.`ExtendedPrice`) AS `ProductSales` from (`Categories` join (`Products` join (`Orders` join `Order Details Extended` on(`Orders`.`OrderID` = `Order Details Extended`.`OrderID`)) on(`Products`.`ProductID` = `Order Details Extended`.`ProductID`)) on(`Categories`.`CategoryID` = `Products`.`CategoryID`)) where `Orders`.`OrderDate` between '1997-01-01' and '1997-12-31' group by `Categories`.`CategoryID`,`Categories`.`CategoryName`,`Products`.`ProductName`;
